// Signs a request to the LendLoop Convex HTTP API.
// Secrets come from the n8n container environment, never from this workflow file.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
const base = $env.LENDLOOP_CONVEX_SITE_URL;
if (!secret || !base) throw new Error('N8N_TO_LENDLOOP_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, path, body = '') {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${method}.${path}.${body}`).digest('hex');
  return { url: base.replace(/\/$/, '') + path, timestamp, signature, body };
}

// Runs whenever a LendLoop workflow fails. Logs it and reports it to Convex,
// where admins see it under "Automation health". No payload data is forwarded.
const e = $input.first().json;
const report = {
  executionId: String((e.execution && e.execution.id) || `trigger-${Date.now()}`),
  workflow: (e.workflow && e.workflow.name) || 'unknown workflow',
  node: (e.execution && e.execution.lastNodeExecuted) || undefined,
  message: String(
    (e.execution && e.execution.error && e.execution.error.message) ||
    (e.trigger && e.trigger.error && e.trigger.error.message) ||
    'Unknown error',
  ).slice(0, 500),
};
console.error(`[LendLoop workflow error] ${JSON.stringify(report)}`);
return [{ json: signed('POST', '/n8n/workflow-error', JSON.stringify(report)) }];
